const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const villarrica = ee.Geometry.Point([-71.93, -39.42]).buffer(5000); // Villarrica volcano, 5km buffer

  // Date ranges
  const startYearHistorical = 2000;
  const endYearHistorical = 2020;
  const startMonthHistorical = 12; // December
  const endMonthHistorical = 1;   // January

  const startDateRecent = '2021-12-01';
  const endDateRecent = '2022-01-31';

  // Scale for reduceRegion. MODIS resolution is ~500m, use 1000m for robustness.
  const scale = 1000;

  // 2. Data Acquisition & Preprocessing
  const modisSnow = ee.ImageCollection('MODIS/061/MOD10A1')
    .select('NDSI_Snow_Cover');

  // Function to mask non-snow values (clouds, water, no data)
  // NDSI_Snow_Cover values 0-100 are snow, 200-255 are non-snow/mask.
  function maskSnow(image) {
    // Keep pixels where NDSI_Snow_Cover is between 0 and 100 (inclusive).
    return image.updateMask(image.gte(0).and(image.lte(100)));
  }

  // Helper function to calculate mean snow cover and pixel count
  async function calculateMeanSnow(collection, geom, periodName) {
    const size = await collection.size().getInfo();
    if (size === 0) {
      console.log(`${periodName} Images: 0`);
      return { mean: null, pixels: 0, size: 0 };
    }

    // Apply cloud mask and take the mean over the collection
    const maskedCollection = collection.map(maskSnow);
    const meanImage = maskedCollection.mean();

    // Calculate mean snow cover and pixel count
    const stats = await meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const meanSnow = stats['NDSI_Snow_Cover_mean'];
    const pixelCount = stats['NDSI_Snow_Cover_count'];

    console.log(`${periodName} Images: ${size} (Val: ${meanSnow !== null ? meanSnow.toFixed(2) : 'N/A'}, Pixels: ${pixelCount})`);

    return { mean: meanSnow, pixels: pixelCount, size: size };
  }

  // --- Calculate for Recent Period (Dec 2021 - Jan 2022) ---
  const recentCollection = modisSnow.filterDate(startDateRecent, endDateRecent)
    .filterBounds(villarrica);
  const recentStats = await calculateMeanSnow(recentCollection, villarrica, 'Recent');

  if (recentStats.size === 0) {
    console.log("No images found for the recent period.");
    console.log("C1");
    return;
  }
  if (recentStats.pixels === 0) {
    console.log("No valid pixels for the recent period after masking.");
    console.log("C2");
    return;
  }
  if (recentStats.mean === null || isNaN(recentStats.mean)) {
    console.log("Calculation failed for the recent period.");
    console.log("C3");
    return;
  }
  const meanSnowRecent = recentStats.mean;

  // --- Calculate for Historical Period (Dec/Jan, 2000-2020) ---
  let historicalCollection = ee.ImageCollection([]);
  for (let year = startYearHistorical; year <= endYearHistorical; year++) {
    // December of the current year
    historicalCollection = historicalCollection.merge(
      modisSnow.filterDate(ee.Date.fromYMD(year, startMonthHistorical, 1), ee.Date.fromYMD(year, startMonthHistorical, 31))
        .filterBounds(villarrica)
    );
    // January of the next year
    if (year < endYearHistorical + 1) { // Ensure we don't go beyond 2021 for Jan
      historicalCollection = historicalCollection.merge(
        modisSnow.filterDate(ee.Date.fromYMD(year + 1, endMonthHistorical, 1), ee.Date.fromYMD(year + 1, endMonthHistorical, 31))
          .filterBounds(villarrica)
      );
    }
  }

  const historicalStats = await calculateMeanSnow(historicalCollection, villarrica, 'Historical');

  if (historicalStats.size === 0) {
    console.log("No images found for the historical period.");
    console.log("C1");
    return;
  }
  if (historicalStats.pixels === 0) {
    console.log("No valid pixels for the historical period after masking.");
    console.log("C2");
    return;
  }
  if (historicalStats.mean === null || isNaN(historicalStats.mean)) {
    console.log("Calculation failed for the historical period.");
    console.log("C3");
    return;
  }
  const meanSnowHistorical = historicalStats.mean;

  // 5. Validation & Final Answer
  console.log(`Mean snow recent: ${meanSnowRecent.toFixed(2)}`);
  console.log(`Mean snow historical: ${meanSnowHistorical.toFixed(2)}`);

  if (meanSnowRecent > meanSnowHistorical) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
